%[text] # Creating Delta V Surrogate
%%
AU = 1.49579151285e8;
mu_star = 1.32712440018e11; % [km3 / s2]
l_star = AU; % [km] one AU
m_star = 3000; % [kg] - max initial ship mass
a_star = mu_star / l_star ^ 2; % [km / s2]
t_star = sqrt(l_star ^ 3 / mu_star);
v_star = sqrt(mu_star/l_star);

year_to_sec = 86400.0 * 365.25;

t0 = 13.2 * year_to_sec / t_star;


u_max = 0.6; % [N]
mu = 1;
mu_dim = mu_star;
m0 = 3000 / m_star * 0.4;
m_min = 500 / m_star; % dependent on a lot
t0 = 13.2 * year_to_sec / t_star;
ToF = 0.5 * year_to_sec / t_star;
tf = ToF;
tf_actual = t0 + ToF;
N = 15;

%% Calculate max dV possible for continuous max thrust (ignoring external forces)
Isp = 4000; % [s]
g_0 = 9.80665; % [m / s2]
alpha = 1 / (Isp * g_0); % [s / m]

mf = m0 - alpha * u_max * tf * t_star / m_star;
dV_max = Isp * g_0 * log(m0 / mf) / 1000 / v_star;
%%
% Load data sets
load("dataset_1to1000IDs_0p5ToF_13p5yr_0p25m.mat")
dataset_0p8ToF_13p2yr = dataset;
dV_filter = dataset_0p8ToF_13p2yr.dV_lambert / dV_max > 0;
dataset_0p8ToF_13p2yr.dV_lambert = dataset_0p8ToF_13p2yr.dV_lambert(dV_filter);
dataset_0p8ToF_13p2yr.dV_lowthrust = dataset_0p8ToF_13p2yr.dV_lowthrust(dV_filter);
dataset_0p8ToF_13p2yr.dV_ratio = dataset_0p8ToF_13p2yr.dV_ratio(dV_filter);
dataset_0p8ToF_13p2yr.v1_ast = dataset_0p8ToF_13p2yr.v1_ast(:, dV_filter);
dataset_0p8ToF_13p2yr.v2_ast = dataset_0p8ToF_13p2yr.v2_ast(:, dV_filter);
dataset_0p8ToF_13p2yr.v1_lambert = dataset_0p8ToF_13p2yr.v1_lambert(:, dV_filter);
dataset_0p8ToF_13p2yr.v2_lambert = dataset_0p8ToF_13p2yr.v2_lambert(:, dV_filter);
dataset_0p8ToF_13p2yr.x_1 = dataset_0p8ToF_13p2yr.x_1(:, dV_filter);
dataset_0p8ToF_13p2yr.x_2 = dataset_0p8ToF_13p2yr.x_2(:, dV_filter);
%%
x_1_me = keplerian_to_modified_equinoctial_array(dataset_0p8ToF_13p2yr.x_1', [])';
x_2_me = keplerian_to_modified_equinoctial_array(dataset_0p8ToF_13p2yr.x_2', [])';
%%
figure %[output:3a80f455]
%scatter3(dataset_0p8ToF_13p2yr.dV_lambert, dataset_0p8ToF_13p2yr.dV_lowthrust, x_1_me(5, :) - x_2_me(5, :)); hold on
scatter3(dataset_0p8ToF_13p2yr.dV_lambert / dV_max, dataset_0p8ToF_13p2yr.dV_lowthrust / dV_max, angdiff(x_1_me(6, :), x_2_me(6, :))); hold on %[output:3a80f455]
xlabel("Lambert dV [km / s]") %[output:3a80f455]
ylabel("Low Thrust dV [km / s]") %[output:3a80f455]
title("Low Thrust dV vs Lambert dV") %[output:3a80f455]
subtitle(sprintf("For %.1f Month Asteroid Transfers at Year %.2f", dataset_0p8ToF_13p2yr.ToF * t_star / year_to_sec * 12, t0 * t_star / year_to_sec)) %[output:3a80f455]
grid on %[output:3a80f455]
hold off %[output:3a80f455]
%%
figure %[output:79ab28be]
scatter(dataset_0p8ToF_13p2yr.dV_lambert / dV_max, dataset_0p8ToF_13p2yr.dV_ratio) %[output:79ab28be]
%%
fitResult_x = {};
%%
h = histfit(dataset_0p8ToF_13p2yr.dV_lambert / dV_max, 100, "normal"); %[output:5dde9ca4]
fitResult_dV_lambert = fitdist(dataset_0p8ToF_13p2yr.dV_lambert' / dV_max, "Normal") % Fit the model to the data %[output:67b0ec57]
%%
histfit(x_1_me(1, :)) %[output:02987175]
fitResult_x{1}{1} = fitdist(x_1_me(1, :)', "Normal") % Fit the model to the data %[output:4f7c0019]
%%
histfit(x_2_me(1, :)) %[output:232a6824]
fitResult_x{1}{2} = fitdist(x_2_me(1, :)', "Normal") % Fit the model to the data %[output:246a2706]
%%
histfit(x_1_me(2, :)) %[output:6de3ee9c]
fitResult_x{2}{1} = fitdist(x_1_me(2, :)', "Normal") % Fit the model to the data %[output:68d1e693]
%%
histfit(x_2_me(2, :)) %[output:56a49b83]
fitResult_x{2}{2} = fitdist(x_2_me(2, :)', "Normal") % Fit the model to the data %[output:96d4eb4d]
%%
histfit(x_1_me(3, :)) %[output:59a1a7b3]
fitResult_x{3}{1} = fitdist(x_1_me(3, :)', "Normal") % Fit the model to the data %[output:26e81ea2]
%%
histfit(x_2_me(3, :)) %[output:2c2e01c3]
fitResult_x{3}{2} = fitdist(x_2_me(3, :)', "Normal") % Fit the model to the data %[output:0c3bc52d]
%%
histfit(x_1_me(4, :)) %[output:9ebc6466]
fitResult_x{4}{1} = fitdist(x_1_me(4, :)', "Normal") % Fit the model to the data %[output:758c8a2e]
%%
histfit(x_2_me(4, :)) %[output:931b70e2]
fitResult_x{4}{2} = fitdist(x_2_me(4, :)', "Normal") % Fit the model to the data %[output:8b036651]
%%
histfit(x_1_me(5, :)) %[output:6c8e05e8]
fitResult_x{5}{1} = fitdist(x_1_me(5, :)', "Normal") % Fit the model to the data %[output:4c8b9118]
%%
histfit(x_2_me(5, :)) %[output:99c1f4d4]
fitResult_x{5}{2} = fitdist(x_2_me(5, :)', "Normal") % Fit the model to the data %[output:80f9f202]
%%
histfit(angdiff(x_1_me(6, :), x_2_me(6, :)), 100, "lognormal") %[output:223ca801]
fitResult_x_me6diff = fitdist(angdiff(x_1_me(6, :), x_2_me(6, :))', "Lognormal") % Fit the model to the data %[output:3abf3260]
%%
histfit(dataset_0p8ToF_13p2yr.v1_ast(3, :) - dataset_0p8ToF_13p2yr.v1_lambert(3, :), 100, "normal") %[output:3131263a]
fitResult_vdiff{1}{1} = fitdist(dataset_0p8ToF_13p2yr.v1_ast(1, :)' - dataset_0p8ToF_13p2yr.v1_lambert(1, :)', "Normal");
fitResult_vdiff{1}{2} = fitdist(dataset_0p8ToF_13p2yr.v2_ast(1, :)' - dataset_0p8ToF_13p2yr.v2_lambert(1, :)', "Normal");
fitResult_vdiff{2}{1} = fitdist(dataset_0p8ToF_13p2yr.v1_ast(2, :)' - dataset_0p8ToF_13p2yr.v1_lambert(2, :)', "Normal");
fitResult_vdiff{2}{2} = fitdist(dataset_0p8ToF_13p2yr.v2_ast(2, :)' - dataset_0p8ToF_13p2yr.v2_lambert(2, :)', "Normal");
fitResult_vdiff{3}{1} = fitdist(dataset_0p8ToF_13p2yr.v1_ast(3, :)' - dataset_0p8ToF_13p2yr.v1_lambert(3, :)', "Normal");
fitResult_vdiff{3}{2} = fitdist(dataset_0p8ToF_13p2yr.v2_ast(3, :)' - dataset_0p8ToF_13p2yr.v2_lambert(3, :)', "Normal");

histfit(dataset_0p8ToF_13p2yr.v2_ast(3, :) - dataset_0p8ToF_13p2yr.v2_lambert(3, :), 100, "normal") %[output:07ba3528]
%%
%[text] ## Surrogate Model using Modified Equinoctial
%[text] 12 Inputs: Lambert dV, x\_1\_me(1:5), x\_2\_me(1:5), angle difference of true longitude         - (give both dV for lambert or actual vecter info? asteroid velocity vectors?)
%[text] 1 Output: Low thrust dV / Lambert dV        - (or just low thrust dV?)
uqlab %[output:3c30d8bd]
%%
% X_inputs = [x_1_me(1, :);
%             x_2_me(1, :);
%             x_1_me(2, :);
%             x_2_me(2, :);
%             x_1_me(3, :);
%             x_2_me(3, :);
%             x_1_me(4, :);
%             x_2_me(4, :);
%             x_1_me(5, :);
%             x_2_me(5, :);
%             dataset_0p8ToF_13p2yr.v1_ast(1, :) - dataset_0p8ToF_13p2yr.v1_lambert(1, :);
%             dataset_0p8ToF_13p2yr.v2_ast(1, :) - dataset_0p8ToF_13p2yr.v2_lambert(1, :);
%             dataset_0p8ToF_13p2yr.v1_ast(2, :) - dataset_0p8ToF_13p2yr.v1_lambert(2, :);
%             dataset_0p8ToF_13p2yr.v2_ast(2, :) - dataset_0p8ToF_13p2yr.v2_lambert(2, :);
%             dataset_0p8ToF_13p2yr.v1_ast(3, :) - dataset_0p8ToF_13p2yr.v1_lambert(3, :);
%             dataset_0p8ToF_13p2yr.v2_ast(3, :) - dataset_0p8ToF_13p2yr.v2_lambert(3, :);
%             dataset_0p8ToF_13p2yr.dV_lambert / dV_max; 
%             angdiff(x_1_me(6, :), x_2_me(6, :))];

X_inputs = [x_1_me(1, :);
            x_2_me(1, :);
            x_1_me(2, :);
            x_2_me(2, :);
            x_1_me(3, :);
            x_2_me(3, :);
            x_1_me(4, :);
            x_2_me(4, :);
            x_1_me(5, :);
            x_2_me(5, :);
            dataset_0p8ToF_13p2yr.v1_ast(1, :) - dataset_0p8ToF_13p2yr.v1_lambert(1, :);
            dataset_0p8ToF_13p2yr.v2_ast(1, :) - dataset_0p8ToF_13p2yr.v2_lambert(1, :);
            dataset_0p8ToF_13p2yr.v1_ast(2, :) - dataset_0p8ToF_13p2yr.v1_lambert(2, :);
            dataset_0p8ToF_13p2yr.v2_ast(2, :) - dataset_0p8ToF_13p2yr.v2_lambert(2, :);
            dataset_0p8ToF_13p2yr.v1_ast(3, :) - dataset_0p8ToF_13p2yr.v1_lambert(3, :);
            dataset_0p8ToF_13p2yr.v2_ast(3, :) - dataset_0p8ToF_13p2yr.v2_lambert(3, :);
            dataset_0p8ToF_13p2yr.dV_lambert / dV_max; 
            angdiff(x_1_me(6, :), x_2_me(6, :))];


index = 1;

InputOpts = [];

% x_1, x_2 ME state
for i = 1 : numel(fitResult_x)
    for j = 1 : 2
        InputOpts.Marginals(index).Name = sprintf('x_%g_%g', j, i);
        InputOpts.Marginals(index).Type = fitResult_x{i}{j}.DistributionName; 
        InputOpts.Marginals(index).Moments = fitResult_x{i}{j}.ParameterValues; % matlab always match UQ lab?
        index = index + 1;
    end
end

% Asteroid and lambert velocity vector differences
for i = 1 : 3
    for j = 1 : 2
        InputOpts.Marginals(index).Name = sprintf('vdiff_%g_%g', j, i);
        InputOpts.Marginals(index).Type = fitResult_vdiff{i}{j}.DistributionName; 
        InputOpts.Marginals(index).Moments = fitResult_vdiff{i}{j}.ParameterValues; % matlab always match UQ lab?
        index = index + 1;
    end
end

% Lambert delta V
InputOpts.Marginals(index).Name = 'dVLambert';
InputOpts.Marginals(index).Type = fitResult_dV_lambert.DistributionName;
InputOpts.Marginals(index).Moments = fitResult_dV_lambert.ParameterValues;
%InputOpts.Marginals(index).Bounds = [0, 1];
index = index + 1;

% True latitude angular difference
InputOpts.Marginals(index).Name = 'Ldiff';
InputOpts.Marginals(index).Type = fitResult_x_me6diff.DistributionName;
InputOpts.Marginals(index).Moments = fitResult_x_me6diff.ParameterValues;

for i = 1 : numel(InputOpts.Marginals)
    if strcmp(InputOpts.Marginals(i).Type, 'Normal')
        InputOpts.Marginals(i).Type = 'Gaussian';
    end
end

myInput = uq_createInput(InputOpts);

uq_print(myInput); %[output:6700e88d]
%%
% Fit
MetaOpts = [];
MetaOpts.Type = 'Metamodel';
MetaOpts.MetaType = 'PCE';

train_portion = 0.7;
indices = [ones([1, floor(train_portion * numel(dataset_0p8ToF_13p2yr.dV_lambert))]), zeros([1, ceil((1 - train_portion) * numel(dataset_0p8ToF_13p2yr.dV_lambert))])];
train_i = logical(indices(randperm(numel(indices))));
test_i = ~train_i;

MetaOpts.ExpDesign.X = X_inputs(:, train_i)';
MetaOpts.ExpDesign.Y = dataset_0p8ToF_13p2yr.dV_lowthrust(train_i)' / dV_max;

MetaOpts.Degree = 1:3;
MetaOpts.Method = 'LARS';

MetaOpts.ValidationSet.X = X_inputs(:, test_i)';
MetaOpts.ValidationSet.Y = dataset_0p8ToF_13p2yr.dV_lowthrust(test_i)' / dV_max;

%MetaOpts.PolyTypes = {'legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre'};
%MetaOpts.PolyTypes = {'arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary'};

myPCE = uq_createModel(MetaOpts); %[output:82d3131b]
uq_print(myPCE) %[output:2e9c5973]
uq_display(myPCE) %[output:654b7779]
%%
%[text] ## Validation
Yval = dataset_0p8ToF_13p2yr.dV_lowthrust(test_i)' / dV_max;

Ylamb = dataset_0p8ToF_13p2yr.dV_lambert(test_i)' / dV_max;

YPCE = uq_evalModel(myPCE, X_inputs(:, test_i)');

uq_figure %[output:8b2041f6]

cmap = uq_colorOrder(3);
uq_histogram(Ylamb, 'FaceColor', cmap(1,:)) %[output:8b2041f6]
hold on %[output:8b2041f6]
uq_histogram(Yval, 'FaceColor', cmap(2,:)) %[output:8b2041f6]
hold on %[output:8b2041f6]
uq_histogram(YPCE, 'FaceColor', cmap(3,:)) %[output:8b2041f6]
hold off %[output:8b2041f6]

xlabel('$\mathrm{Y}$') %[output:8b2041f6]
ylabel('Counts') %[output:8b2041f6]
uq_legend(... %[output:group:02a9b195] %[output:8b2041f6]
    {'Lambert', 'True model response', 'PCE prediction'},... %[output:8b2041f6]
    'Location', 'northwest') %[output:group:02a9b195] %[output:8b2041f6]

uq_figure
%%
uq_plot(Ylamb, Yval, 'x') %[output:363568a9]
hold on %[output:363568a9]
uq_plot(YPCE, Yval, '+') %[output:363568a9]
hold on %[output:363568a9]
uq_plot([min(Yval) max(Yval)], [min(Yval) max(Yval)], 'k') %[output:363568a9]
hold off %[output:363568a9]

axis equal %[output:363568a9]
axis([min(Yval) max(Yval) min(Yval) max(Yval)]) %[output:363568a9]

ylabel('$\mathrm{Y_{true}}$') %[output:363568a9]
xlabel('$\mathrm{Y_{Lamb,PCE}}$') %[output:363568a9]
legend("Lamb", "PCE") %[output:363568a9]
%%
fprintf('PCE metamodel validation error: %5.4e\n', myPCE.Error.Val) %[output:27f4d5b5]
fprintf('PCE metamodel LOO error:        %5.4e\n', myPCE.Error.LOO) %[output:1e230f3f]
